import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {webcrypto} from 'node:crypto';
globalThis.crypto ??= webcrypto;
const text=await readFile(new URL('./browser_proxy.js',import.meta.url),'utf8');
const {default:worker}=await import('data:text/javascript;base64,'+Buffer.from(text).toString('base64'));
const auth='Basic '+btoa('fixture-owner:fixture-password-only');
const digest=Buffer.from(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(auth))).toString('hex');
const env={BROWSER_AUTH_SHA256:digest,BROWSER_ORIGIN_PREFIX:'/_fixture',BROWSER_ORIGIN_TOKEN:'fixture-origin'};
let upstream=[];
globalThis.fetch=async (url,options)=>{upstream.push({url:String(url),headers:new Headers(options.headers)});return new Response('<html><head></head><body>fixture</body></html>',{headers:{'Content-Type':'text/html'}})};
const request=(headers={},path='/',method='GET',binding=env)=>worker.fetch(new Request('https://browser.leonmingod.com'+path,{method,headers}),binding);
assert.equal((await request()).status,401);
assert.equal((await request({Authorization:'Basic wrong'})).status,401);
assert.equal((await request({},'/', 'GET',{})).status,503);
const first=await request({Authorization:auth});assert.equal(first.status,200);
const setCookie=first.headers.get('Set-Cookie');
for(const flag of ['__Host-rak_chrome=','Path=/','Secure','HttpOnly','SameSite=Strict','Max-Age=28800'])assert.ok(setCookie.includes(flag));
assert.ok(!setCookie.includes('Domain='));
const cookie=setCookie.split(';',1)[0];
assert.ok(!cookie.includes(auth)&&!cookie.includes('fixture-password'));
assert.equal((await request({Cookie:cookie+'; retained=fixture'},'/websockets')).status,200);
assert.equal(upstream.at(-1).headers.get('Authorization'),auth);
assert.equal(upstream.at(-1).headers.get('Cookie'),'retained=fixture');
let n=upstream.length;
assert.equal((await request({Cookie:cookie,Upgrade:'websocket',Origin:'https://browser.leonmingod.com'},'/websockets')).status,200);
assert.equal(upstream.length,n+1);
n=upstream.length;
assert.equal((await request({Cookie:cookie,Upgrade:'websocket',Origin:'https://attacker.invalid'},'/websockets')).status,403);
assert.equal((await request({Cookie:cookie,Origin:'https://attacker.invalid'},'/api/input','POST')).status,403);
assert.equal(upstream.length,n);
const p=cookie.split('.');p[2]=(p[2][0]==='A'?'B':'A')+p[2].slice(1);
assert.equal((await request({Cookie:p.join('.')})).status,401);
assert.equal((await request({Cookie:cookie},'/', 'GET',{...env,BROWSER_AUTH_SHA256:'0'.repeat(64)})).status,401);
const original=Date.now;Date.now=()=>original()+28801000;
try{assert.equal((await request({Cookie:cookie})).status,401)}finally{Date.now=original}
console.log('PASS: private browser session authentication, tampering, expiry, key rotation, cross-site rejection and origin credentials');
